/bin/zsh -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#141211">
<title>Codex</title>
<style>
@import url('"'https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600&family=Italiana&display=swap');
:root{color-scheme:dark;--ink:#eee8df;--muted:#a09b92;--accent:#efaa73}*{box-sizing:border-box}body{margin:0;overflow:hidden;background:#141211;color:var(--ink);font-family:'DM Sans',system-ui,sans-serif}canvas{display:block;touch-action:none}#scene{position:fixed;inset:0}header{position:fixed;left:4.3vw;top:38px;pointer-events:none}h1{font-family:'Italiana',Georgia,serif;font-size:54px;font-weight:400;letter-spacing:-2px;line-height:1;margin:0 0 16px}.intro{font-size:12px;color:#b6afa6;letter-spacing:.03em;line-height:1.7;margin:0}.edition{position:fixed;right:4.3vw;top:43px;color:#8d8981;font-size:10px;letter-spacing:.19em;display:flex;gap:14px;align-items:center}.edition span{width:25px;height:1px;background:#71675b}.panel{position:fixed;left:4.3vw;bottom:72px;width:270px;padding:22px 22px 19px;border:1px solid #ffffff14;border-radius:15px;background:linear-gradient(140deg,#272523bb,#1c1a19d9);backdrop-filter:blur(22px);box-shadow:0 16px 50px #0002}.panel-top{display:flex;justify-content:space-between;align-items:center;padding-bottom:19px;border-bottom:1px solid #ffffff12}.label{font-size:11px;font-weight:500;letter-spacing:.02em}.power-text{display:flex;gap:8px;align-items:center;font-size:11px;color:#c4bdb2}.dot{width:5px;height:5px;border-radius:50%;background:#f3b17b;box-shadow:0 0 10px #ff9d6388}.toggle{border:0;background:#c3895c;width:32px;height:18px;border-radius:20px;position:relative;cursor:pointer;padding:0}.toggle:after{content:'';width:12px;height:12px;top:3px;left:17px;position:absolute;background:#fff3e1;border-radius:50%;transition:left .25s}.toggle[aria-checked=false]{background:#55504a}.toggle[aria-checked=false]:after{left:3px}.row-title{display:flex;justify-content:space-between;align-items:center;margin:20px 0 12px}.value{font-size:10px;color:var(--muted);font-variant-numeric:tabular-nums}.swatches{display:flex;gap:12px}.swatch{--a:#ff6631;--b:#ffcc5b;width:36px;height:36px;border-radius:50%;border:1px solid #ffffff20;background:radial-gradient(circle at 35% 30%,var(--b),var(--a) 65%,#301719);cursor:pointer;position:relative;box-shadow:inset 0 1px 4px #ffffff35;transition:transform .2s}.swatch:hover{transform:translateY(-2px)}.swatch[aria-pressed=true]:after{content:'';position:absolute;inset:-5px;border:1px solid #d4baa0;border-radius:50%}.swatch[aria-pressed=true]:before{content:'';position:absolute;left:13px;top:13px;width:8px;height:8px;background:#fff1dd;border-radius:50%;box-shadow:0 0 5px #fff8}.range{width:100%;height:3px;appearance:none;background:linear-gradient(to right,#b9916a 50%,#ffffff1c 50%);border-radius:4px;display:block;cursor:pointer;margin:16px 0 6px}.range::-webkit-slider-thumb{appearance:none;width:10px;height:10px;border-radius:50%;background:#e0cfb9;box-shadow:0 0 0 4px #e0cfb90a}.range::-moz-range-thumb{width:10px;height:10px;border:0;border-radius:50%;background:#e0cfb9}.range:focus-visible,.toggle:focus-visible,.swatch:focus-visible{outline:2px solid #efaa73;outline-offset:6px}.orbit-row{margin-top:21px;padding-top:16px;border-top:1px solid #ffffff12;display:flex;justify-content:space-between;align-items:center}.orbit-button{font:inherit;font-size:10px;color:#bcb3a6;background:none;border:0;cursor:pointer;display:flex;align-items:center;gap:7px;padding:0}.orbit-button svg{opacity:.7}.orbit-button[aria-pressed=true]{color:#efaa73}.tiny{font-size:9px;letter-spacing:.04em;color:#77736c}footer{position:fixed;bottom:27px;left:4.3vw;right:4.3vw;display:flex;align-items:center;justify-content:space-between;color:#817c75;font-size:10px;letter-spacing:.02em;pointer-events:none}.instructions{display:flex;align-items:center;gap:9px}.instructions svg{opacity:.65}.status{display:flex;align-items:center;gap:9px;font-size:9px;letter-spacing:.14em;text-transform:uppercase}.status i{width:4px;height:4px;background:#c39167;border-radius:50%}#error{position:fixed;top:45%;left:50%;transform:translate(-50%,-50%);max-width:400px;font-size:14px;line-height:1.7;display:none}#loading{position:fixed;left:56%;top:50%;color:#c1a789;font-size:11px;letter-spacing:.15em;transition:opacity .8s;pointer-events:none}@media(max-width:700px){header{left:25px;top:25px}h1{font-size:40px;margin-bottom:10px}.intro{font-size:10px}.edition{right:24px;top:30px;font-size:8px}.panel{left:20px;bottom:57px;width:205px;padding:16px;transform-origin:bottom left}.row-title{margin-top:14px;margin-bottom:10px}.swatch{width:29px;height:29px}.swatch[aria-pressed=true]:before{left:10px;top:10px}.swatches{gap:11px}.orbit-row{margin-top:14px;padding-top:12px}.panel-top{padding-bottom:12px}.label{font-size:10px}footer{left:22px;right:22px;bottom:22px}.instructions{font-size:9px}.tiny{display:none}.status{font-size:8px}#loading{left:50%}}
</style>
<script type=\"importmap\">{\"imports\":{\"three\":\"https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js\",\"three/addons/\":\"https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/\"}}</script>
</head>
<body>
<div id=\"scene\"></div>
<header><h1>Codex</h1><p class=\"intro\">A little warmth.<br>A moment to slow down.</p></header>
<div class=\"edition\"><span></span> AN OBJECT IN MOTION</div>
<section class=\"panel\" aria-label=\"Lamp controls\">
<div class=\"panel-top\"><div class=\"power-text\"><span class=\"dot\" id=\"power-dot\"></span><span id=\"power-label\">Lamp is on</span></div><button class=\"toggle\" id=\"power\" role=\"switch\" aria-checked=\"true\" aria-label=\"Lamp power\"></button></div>
<div class=\"row-title\"><span class=\"label\">Atmosphere</span><span class=\"value\" id=\"palette-name\">Ember</span></div>
<div class=\"swatches\" role=\"group\" aria-label=\"Color presets\">
<button class=\"swatch\" aria-label=\"Ember: red wax, golden liquid\" aria-pressed=\"true\" data-preset=\"0\" style=\"--a:#e9471d;--b:#ffd26b\"></button>
<button class=\"swatch\" aria-label=\"Lagoon: turquoise wax, blue liquid\" aria-pressed=\"false\" data-preset=\"1\" style=\"--a:#13ae9b;--b:#9eead5\"></button>
<button class=\"swatch\" aria-label=\"Dusk: pink wax, violet liquid\" aria-pressed=\"false\" data-preset=\"2\" style=\"--a:#b64da2;--b:#f6b2dc\"></button>
<button class=\"swatch\" aria-label=\"Honey: amber wax, pale cream liquid\" aria-pressed=\"false\" data-preset=\"3\" style=\"--a:#b87d20;--b:#ffe3a0\"></button>
</div>
<label class=\"row-title\" for=\"heat\"><span class=\"label\">Heat & flow</span><output class=\"value\" id=\"heat-value\">65%</output></label><input class=\"range\" id=\"heat\" type=\"range\" min=\"20\" max=\"100\" value=\"65\" aria-label=\"Heat and flow\">
<label class=\"row-title\" for=\"amount\"><span class=\"label\">Wax volume</span><output class=\"value\" id=\"amount-value\">60%</output></label><input class=\"range\" id=\"amount\" type=\"range\" min=\"20\" max=\"100\" value=\"60\" aria-label=\"Wax volume\">
<div class=\"orbit-row\"><button class=\"orbit-button\" id=\"orbit\" aria-pressed=\"false\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 20 20\" fill=\"none\"><ellipse cx=\"10\" cy=\"10\" rx=\"9\" ry=\"4.5\" stroke=\"currentColor\"/><path d=\"m14 3 2 4-4 1\" stroke=\"currentColor\"/></svg>Auto orbit</button><span class=\"tiny\">Take your time</span></div>
</section>
<footer><span class=\"instructions\"><svg width=\"13\" height=\"15\" viewBox=\"0 0 13 15\" fill=\"none\"><rect x=\"2\" y=\"1\" width=\"9\" height=\"13\" rx=\"4.5\" stroke=\"currentColor\"/><path d=\"M6.5 3v3\" stroke=\"currentColor\"/></svg>Drag to explore <span style=\"opacity:.4;padding:0 5px\">/</span> Scroll to get closer</span><span class=\"status\"><i></i><span id=\"state\">Warming the room</span></span></footer>
<div id=\"loading\">GATHERING A LITTLE LIGHT</div><div id=\"error\"></div>
<script type=\"module\">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color('#141312');
scene.fog = new THREE.FogExp2('#141312',.027);
const renderer = new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);
renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
document.querySelector('#scene').appendChild(renderer.domElement);
const camera=new THREE.PerspectiveCamera(36,innerWidth/innerHeight,.1,65);
camera.position.set(7,4.3,11.8);
const orbit=new OrbitControls(camera,renderer.domElement);
orbit.target.set(-.65,2.65,0);orbit.enableDamping=true;orbit.dampingFactor=.045;
orbit.minDistance=6.5;orbit.maxDistance=20;orbit.maxPolarAngle=Math.PI*.49;orbit.minPolarAngle=.3;orbit.enablePan=false;orbit.autoRotateSpeed=.4;
const pmrem=new THREE.PMREMGenerator(renderer);
const room=new RoomEnvironment();
scene.environment=pmrem.fromScene(room,.04).texture;scene.environmentIntensity=.35;room.dispose();pmrem.dispose();
const ambient=new THREE.HemisphereLight('#a2b1bc','#302214',.32);scene.add(ambient);
const key=new THREE.RectAreaLight('#d9e4f0',2.5,2.3,6);key.position.set(-4,4,4);key.lookAt(0,2.5,0);scene.add(key);
const rim=new THREE.DirectionalLight('#b5a995',1.1);rim.position.set(3,6,-3);scene.add(rim);
const bulb=new THREE.PointLight('#ff8534',34,10,2);bulb.position.set(0,1.2,0);bulb.castShadow=true;bulb.shadow.mapSize.set(512,512);bulb.shadow.normalBias=.04;bulb.shadow.bias=-.002;bulb.shadow.radius=5;scene.add(bulb);
const spill=new THREE.PointLight('#ff7131',12,8,2);spill.position.set(0,2.6,.5);scene.add(spill);
const wallLight=new THREE.PointLight('#ff943e',11,9,2);wallLight.position.set(0,1.7,-.9);scene.add(wallLight);

function canvasTexture(draw,size=512){const c=document.createElement('canvas');c.width=c.height=size;draw(c.getContext('2d'),size);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t;}
const wood=canvasTexture((ctx,s)=>{ctx.fillStyle='#40342a';ctx.fillRect(0,0,s,s);let seed=37;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let i=0;i<2500;i++){const y=rand()*s;ctx.strokeStyle="'`rgba(${rand()>.5?'"'15,9,5':'115,83,54'},"'${rand()*.13})`;ctx.lineWidth=rand()*1.2+.3;ctx.beginPath();for(let x=0;x<=s;x+=8){const yy=y+Math.sin(x*.012+y*.04)*1.8+Math.sin(x*.04+y)*.4;x?ctx.lineTo(x,yy):ctx.moveTo(x,yy)}ctx.stroke();}},1024);wood.wrapS=wood.wrapT=THREE.RepeatWrapping;wood.repeat.set(3,3);wood.anisotropy=8;
const table=new THREE.Mesh(new THREE.BoxGeometry(22,.18,18),new THREE.MeshStandardMaterial({map:wood,roughness:.36,metalness:.05}));table.position.set(0,-.1,0);table.receiveShadow=true;scene.add(table);
const wall=new THREE.Mesh(new THREE.PlaneGeometry(35,15),new THREE.MeshStandardMaterial({color:'"'#39352f',roughness:.95}));wall.position.set(0,6,-4.4);wall.receiveShadow=true;scene.add(wall);
const skirting=new THREE.Mesh(new THREE.BoxGeometry(30,.09,.1),new THREE.MeshStandardMaterial({color:'#25231f',roughness:.7}));skirting.position.set(0,.12,-4.35);scene.add(skirting);
// Lathed, double-walled borosilicate vessel; all dimensions are in tabletop scale.
function lathe(points,mat){const mesh=new THREE.Mesh(new THREE.LatheGeometry(points.map(p=>new THREE.Vector2(...p)),128),mat);scene.add(mesh);return mesh;}
const metal=new THREE.MeshPhysicalMaterial({color:'#9f9990',metalness:1,roughness:.25,clearcoat:.3,clearcoatRoughness:.26});
const darkMetal=new THREE.MeshStandardMaterial({color:'#494744',metalness:.95,roughness:.29});
lathe([[0,.02],[.69,.02],[.75,.045],[.77,.085],[.77,.15],[.74,.18],[.39,.91],[.4,.99],[.61,1.04],[.67,1.12],[.67,1.2],[.63,1.24],[0,1.24]],metal).castShadow=true;
function ring(r,y,t,mat){const m=new THREE.Mesh(new THREE.TorusGeometry(r,t,12,128),mat);m.rotation.x=Math.PI/2;m.position.y=y;scene.add(m);return m;}
ring(.756,.13,.012,darkMetal);ring(.651,1.17,.014,darkMetal);
const glassMat=new THREE.MeshPhysicalMaterial({color:'#fff4d6',metalness:0,roughness:.055,transmission:1,thickness:.065,ior:1.46,envMapIntensity:1.1,clearcoat:1,clearcoatRoughness:.07,attenuationColor:new THREE.Color('#fbd877'),attenuationDistance:5,side:THREE.FrontSide});
const profile=[[0,1.15],[.57,1.15],[.632,1.19],[.656,1.28],[.65,1.4],[.612,1.9],[.565,2.5],[.52,3.1],[.47,3.7],[.425,4.28],[.406,4.58],[.384,4.72],[.32,4.8],[0,4.81],[0,4.755],[.30,4.755],[.345,4.69],[.368,4.57],[.387,4.28],[.432,3.7],[.482,3.1],[.527,2.5],[.574,1.9],[.612,1.4],[.615,1.29],[.593,1.24],[0,1.24]];
const glass=lathe(profile,glassMat);glass.renderOrder=3;
lathe([[0,4.73],[.389,4.73],[.415,4.77],[.416,4.85],[.215,5.38],[.19,5.415],[0,5.425]],metal).castShadow=true;ring(.41,4.8,.01,darkMetal);
const bulbMesh=new THREE.Mesh(new THREE.SphereGeometry(.31,32,24),new THREE.MeshBasicMaterial({color:new THREE.Color(6,2,.4)}));bulbMesh.scale.y=.3;bulbMesh.position.y=1.235;scene.add(bulbMesh);
// A recessed toggle, and a cord lying on the table before falling out of frame.
const switchBase=new THREE.Mesh(new THREE.BoxGeometry(.12,.16,.045),darkMetal);switchBase.position.set(.36,.45,.44);switchBase.rotation.y=.65;scene.add(switchBase);
const switchLever=new THREE.Mesh(new THREE.BoxGeometry(.075,.095,.04),new THREE.MeshStandardMaterial({color:'#1c1b19',roughness:.35}));switchLever.position.set(.375,.46,.469);switchLever.rotation.set(-.2,.65,0);scene.add(switchLever);
const cordPath=new THREE.CatmullRomCurve3([new THREE.Vector3(.2,.07,-.6),new THREE.Vector3(.75,.035,-.9),new THREE.Vector3(1.6,.025,-.7),new THREE.Vector3(2.5,.025,-.3),new THREE.Vector3(3.35,.025,-.55),new THREE.Vector3(4.3,.025,-1.15),new THREE.Vector3(5.5,.025,-1.35),new THREE.Vector3(7,.025,-1.1),new THREE.Vector3(11,.025,-1.7)]);
const cord=new THREE.Mesh(new THREE.TubeGeometry(cordPath,100,.025,10,false),new THREE.MeshStandardMaterial({color:'#151412',roughness:.56}));cord.castShadow=true;scene.add(cord);
// Quiet props establish scale without competing with the lamp.
const bookMat=new THREE.MeshStandardMaterial({color:'#302e28',roughness:.94});
const book=new THREE.Mesh(new THREE.BoxGeometry(1.5,.17,2.05),bookMat);book.position.set(3.6,.08,-2.2);book.rotation.y=-.25;book.castShadow=true;scene.add(book);
const pages=new THREE.Mesh(new THREE.BoxGeometry(1.43,.115,1.96),new THREE.MeshStandardMaterial({color:'#b1a594',roughness:1}));pages.position.copy(book.position);pages.position.y+=.015;pages.rotation.copy(book.rotation);scene.add(pages);
const cup=lathe([[.32,0],[.34,.03],[.34,.42],[.32,.44],[.285,.44],[.29,.07],[0,.07],[0,0]],new THREE.MeshStandardMaterial({color:'#3a3933',roughness:.45}));cup.position.set(-3,.0,-2.6);cup.castShadow=true;

const N=14;
const blobUniform=Array.from({length:N},()=>new THREE.Vector4());
const shapeUniform=Array.from({length:N},()=>new THREE.Vector4());
const waxUniforms={uBlobs:{value:blobUniform},uShape:{value:shapeUniform},uWax:{value:new THREE.Color('#ea3910')},uLiquid:{value:new THREE.Color('#e7ad35')},uTime:{value:0},uPower:{value:1},uPool:{value:.14},uCamera:{value:camera.position},uViewProjection:{value:new THREE.Matrix4()}};
const waxMaterial=new THREE.ShaderMaterial({uniforms:waxUniforms,vertexShader:"'`varying vec3 vWorld;void main(){vWorld=(modelMatrix*vec4(position,1.)).xyz;gl_Position=projectionMatrix*viewMatrix*vec4(vWorld,1.);}`,fragmentShader:`
precision highp float;
varying vec3 vWorld;
uniform vec4 uBlobs[14];uniform vec4 uShape[14];
uniform vec3 uWax,uLiquid,uCamera;uniform float uTime,uPower,uPool;uniform mat4 uViewProjection;
float smin(float a,float b,float k){float h=clamp(.5+.5*(b-a)/k,0.,1.);return mix(b,a,h)-k*h*(1.-h);}
float vessel(vec3 p){float r=.619-(p.y-1.3)*.077;return max(length(p.xz)-r,max(1.265-p.y,p.y-4.69));}
float field(vec3 p){float d=(p.y-(1.29+uPool))*.8;for(int i=0;i<14;i++){vec3 q=p-uBlobs[i].xyz;vec3 ax=uShape[i].xyz; q.x+=sin(q.y*5.+uTime*.6+float(i))*0.022;q.z+=sin(q.y*4.-uTime*.47+float(i)*2.)*.017;float e=(length(q/ax)-1.)*min(ax.x,min(ax.y,ax.z));d=smin(d,e,.135);}return max(d,vessel(p)+.012);}
vec3 normalAt(vec3 p){vec2 e=vec2(.002,0.);return normalize(vec3(field(p+e.xyy)-field(p-e.xyy),field(p+e.yxy)-field(p-e.yxy),field(p+e.yyx)-field(p-e.yyx)));}
void main(){vec3 ro=uCamera;vec3 rd=normalize(vWorld-ro);vec3 inv=1./rd;vec3 ta=(vec3(-.68,1.25,-.68)-ro)*inv;vec3 tb=(vec3(.68,4.73,.68)-ro)*inv;vec3 tn=min(ta,tb),tf=max(ta,tb);float t=max(max(tn.x,tn.y),tn.z);float end=min(min(tf.x,tf.y),tf.z);t=max(t,0.);bool hit=false;vec3 p;
for(int i=0;i<86;i++){p=ro+rd*t;float d=field(p);if(d<.0018){hit=true;break;}t+=max(d*.8,.002);if(t>end)break;}if(!hit)discard;
vec3 n=normalAt(p);vec3 l=normalize(vec3(-.1,1.24,.1)-p);float diffuse=max(dot(n,l),0.);float fres=pow(1.-max(dot(n,-rd),0.),3.);float h=clamp((p.y-1.25)/3.5,0.,1.);float thick=clamp(-field(p-rd*.12)*8.,0.,1.);float heat=exp(-(p.y-1.25)*1.05);float thin=1.-thick;
vec3 c=uWax*(.24+diffuse*.48+thin*.32);c+=uWax*(.8+heat*2.7)*uPower;c=mix(c,c*vec3(.7,.55,.5),h*.34);c+=mix(uWax,vec3(1.,.7,.3),.45)*pow(fres,1.5)*(.14+uPower*.85);vec3 halfv=normalize(normalize(vec3(-3.,5.,4.)-p)-rd);c+=vec3(1.,.77,.48)*pow(max(dot(n,halfv),0.),65.)*.65;c*=.85+.15*sin(p.y*2.+uTime*.13);c=mix(c,vec3(.065,.025,.018)+uWax*.11,1.-(.15+uPower*.85));gl_FragColor=vec4(c,1.);
vec4 clip=uViewProjection*vec4(p,1.);gl_FragDepth=(clip.z/clip.w)*.5+.5;
#include <tonemapping_fragment>
#include <colorspace_fragment>
}`});
const wax=new THREE.Mesh(new THREE.BoxGeometry(1.36,3.48,1.36),waxMaterial);wax.position.y=2.99;wax.frustumCulled=false;scene.add(wax);
// Liquid is an optically closed volume beneath the separate thick glass shell.
const liquidMat=new THREE.MeshPhysicalMaterial({color:'"'#ffe59b',transmission:1,roughness:.08,thickness:.85,ior:1.333,attenuationColor:new THREE.Color('#ffc54b'),attenuationDistance:2.9,transparent:true,opacity:.2,depthWrite:false,side:THREE.DoubleSide,envMapIntensity:.3});
const liquid=lathe([[0,1.27],[.603,1.27],[.603,1.4],[.565,1.9],[.519,2.5],[.474,3.1],[.424,3.7],[.379,4.28],[.36,4.58],[.34,4.66],[0,4.66]],liquidMat);liquid.renderOrder=2;
// Soft optical light spill: a procedural radial texture, not an image asset.
const glowTexture=canvasTexture((ctx,s)=>{const g=ctx.createRadialGradient(s/2,s/2,0,s/2,s/2,s/2);g.addColorStop(0,'rgba(255,255,255,.5)');g.addColorStop(.23,'rgba(255,255,255,.2)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,s,s);},128);
const glow=new THREE.Mesh(new THREE.PlaneGeometry(6,6),new THREE.MeshBasicMaterial({map:glowTexture,color:'#ff963c',transparent:true,opacity:.25,depthWrite:false,blending:THREE.AdditiveBlending}));glow.rotation.x=-Math.PI/2;glow.position.y=.002;scene.add(glow);
const composer=new EffectComposer(renderer);composer.addPass(new RenderPass(scene,camera));
const bloom=new UnrealBloomPass(new THREE.Vector2(innerWidth,innerHeight),.32,.6,1.2);composer.addPass(bloom);composer.addPass(new OutputPass());

// Thermal parcels carry conserved wax volume. Temperature drives buoyancy;
// the smooth implicit field fuses parcels into one continuous visible volume.
let seed=9271;function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
const parcels=Array.from({length:N},(_,i)=>({x:(random()-.5)*.32,z:(random()-.5)*.32,y:i<3?1.4:1.55+random()*2.85,v:0,temp:i<3?.85:random(),r:.13+random()*.15,phase:random()*6.28,age:random()*20}));
let powered=true,powerLevel=1,thermal=1,heat=.65,amount=.6,time=0,accumulator=0,last=performance.now(),smoothAmount=.6;
let preset=0;const presets=[{name:'Ember',wax:'#ed350b',liquid:'#f8cb59',light:'#ff8335'},{name:'Lagoon',wax:'#15c9a3',liquid:'#8ac9da',light:'#66e5c2'},{name:'Dusk',wax:'#f24c91',liquid:'#a185d3',light:'#e778ba'},{name:'Honey',wax:'#f6a62b',liquid:'#f1d6a0',light:'#ffbd5b'}];
